// Generated by `pnpm emit:native` from the catalogue. Never hand-edited: change the
// system or palette in design/ and run `pnpm emit:native` again.

import '../pm_theme.dart';
import 'desktop_azure.dart' as desktop_azure_lib;
import 'dew_verdigris.dart' as dew_verdigris_lib;
import 'flint_cobalt.dart' as flint_cobalt_lib;
import 'glassmorphic_azure.dart' as glassmorphic_azure_lib;
import 'harbor_ember.dart' as harbor_ember_lib;
import 'journal_umber.dart' as journal_umber_lib;
import 'pastel_amethyst.dart' as pastel_amethyst_lib;
import 'pebble_azure.dart' as pebble_azure_lib;
import 'plain_neutral.dart' as plain_neutral_lib;
import 'pop_orchid.dart' as pop_orchid_lib;
import 'press_carmine.dart' as press_carmine_lib;
import 'terminal_petrol.dart' as terminal_petrol_lib;

/// Every pairing this package carries: each house system with its default palette.
abstract final class PMThemes {
  /// desktop/azure.
  static const PMTheme desktop_azure = desktop_azure_lib.theme;

  /// dew/verdigris.
  static const PMTheme dew_verdigris = dew_verdigris_lib.theme;

  /// flint/cobalt.
  static const PMTheme flint_cobalt = flint_cobalt_lib.theme;

  /// glassmorphic/azure.
  static const PMTheme glassmorphic_azure = glassmorphic_azure_lib.theme;

  /// harbor/ember.
  static const PMTheme harbor_ember = harbor_ember_lib.theme;

  /// journal/umber.
  static const PMTheme journal_umber = journal_umber_lib.theme;

  /// pastel/amethyst.
  static const PMTheme pastel_amethyst = pastel_amethyst_lib.theme;

  /// pebble/azure.
  static const PMTheme pebble_azure = pebble_azure_lib.theme;

  /// plain/neutral.
  static const PMTheme plain_neutral = plain_neutral_lib.theme;

  /// pop/orchid.
  static const PMTheme pop_orchid = pop_orchid_lib.theme;

  /// press/carmine.
  static const PMTheme press_carmine = press_carmine_lib.theme;

  /// terminal/petrol.
  static const PMTheme terminal_petrol = terminal_petrol_lib.theme;

  /// Every pairing, in system order.
  static const List<PMTheme> catalogue = [
    desktop_azure,
    dew_verdigris,
    flint_cobalt,
    glassmorphic_azure,
    harbor_ember,
    journal_umber,
    pastel_amethyst,
    pebble_azure,
    plain_neutral,
    pop_orchid,
    press_carmine,
    terminal_petrol,
  ];

  /// The pairing of [system] and [palette], or null when this package does not carry it.
  static PMTheme? named(String system, String palette) => switch ('$system/$palette') {
    'desktop/azure' => desktop_azure,
    'dew/verdigris' => dew_verdigris,
    'flint/cobalt' => flint_cobalt,
    'glassmorphic/azure' => glassmorphic_azure,
    'harbor/ember' => harbor_ember,
    'journal/umber' => journal_umber,
    'pastel/amethyst' => pastel_amethyst,
    'pebble/azure' => pebble_azure,
    'plain/neutral' => plain_neutral,
    'pop/orchid' => pop_orchid,
    'press/carmine' => press_carmine,
    'terminal/petrol' => terminal_petrol,
    _ => null,
  };
}
